INSERT INTO veloryz_studio.query_contracts(key,query) VALUES (encode(sha256(convert_to($contract$SELECT pay.reference,pay.title,pay.amount_paise,pay.status,pay.created_at FROM veloryz_studio.studio_payments pay JOIN veloryz_studio.studio_client_projects p ON p.request_reference=pay.reference WHERE p.id=? AND p.request_reference<>'' ORDER BY pay.created_at DESC LIMIT 50$contract$,'UTF8')),'hex'),$contract$SELECT pay.reference,pay.title,pay.amount_paise,pay.status,pay.created_at FROM veloryz_studio.studio_payments pay JOIN veloryz_studio.studio_client_projects p ON p.request_reference=pay.reference WHERE p.id=? AND p.request_reference<>'' ORDER BY pay.created_at DESC LIMIT 50$contract$) ON CONFLICT(key) DO UPDATE SET query=EXCLUDED.query;
